import json, sys
d=json.load(open(sys.argv[1]))
r=d['rollout']
print("SCORE reward:", d['score']['reward'])
print("FEEDBACK:", d['score']['feedback'])
print("="*80)
md=d['rollout'].get('metadata',{})
# print gold actions
for ac in md.get('tau2_reward_info',{}).get('action_checks',[]):
    a=ac['action']
    print(f"[GOLD ACTION] {a['name']}({json.dumps(a['arguments'])}) match={ac['action_match']}")
print("="*80)
for m in r['output']:
    role=m.get('role')
    content=m.get('content')
    tcs=m.get('tool_calls')
    if role=='user':
        print(f"\n--- USER: {content}")
    elif role=='assistant':
        if content: print(f"\nASSISTANT: {content}")
        if tcs:
            for tc in tcs:
                fn=tc.get('function',{})
                print(f"  >> CALL {fn.get('name')}({fn.get('arguments')})")
    elif role=='tool':
        print(f"  << TOOL RESULT: {str(content)[:600]}")
    else:
        print(f"[{role}] {str(content)[:300]}")
